"""The YouTube account the GPU box downloads with: checked, trimmed to YouTube and Google, set by the owner only."""

import time

import pytest

from web_deploy.gateway import youtube_cookies
from web_deploy.gateway.admin_cli import main
from web_deploy.gateway.store import OWNER_FIRM
from web_deploy.tests.gateway.support import CONSOLE_PASSWORD, signed_in

LATER = int(time.time()) + 30 * 86400
EXPORT = "\n".join([
    "# Netscape HTTP Cookie File",
    "# This file is generated by an extension. Do not edit.",
    "",
    f".youtube.com\tTRUE\t/\tTRUE\t{LATER}\tSAPISID\tabc",
    f"#HttpOnly_.youtube.com\tTRUE\t/\tTRUE\t{LATER + 99}\tLOGIN_INFO\tdef",
    f".google.com\tTRUE\t/\tTRUE\t{LATER}\tNID\tghi",
    f".bank.example\tTRUE\t/\tTRUE\t{LATER}\tsession\tsecret-elsewhere",
    "",
])


@pytest.fixture
def path(tmp_path):
    return tmp_path / "state" / "youtube_cookies.txt"


class TestStore:
    def test_only_youtube_and_google_cookies_are_kept_readable_by_the_gateway_alone(self, path):
        state = youtube_cookies.set_cookies(path, EXPORT)

        text = path.read_text()
        assert "secret-elsewhere" not in text and "SAPISID" in text and "NID" in text
        assert path.stat().st_mode & 0o777 == 0o600
        assert (state["present"], state["cookies"], state["signed_in"], state["expires"], state["expired"]) == \
            (True, 3, True, LATER, False)

    def test_an_anonymous_export_is_kept_but_flagged(self, path):
        anonymous = f".youtube.com\tTRUE\t/\tTRUE\t{LATER}\tVISITOR_INFO1_LIVE\tx\n"
        assert youtube_cookies.set_cookies(path, anonymous)["signed_in"] is False

    def test_expired_sign_in_is_flagged(self, path):
        youtube_cookies.set_cookies(path, f".youtube.com\tTRUE\t/\tTRUE\t{int(time.time()) - 60}\tSAPISID\tx\n")
        assert youtube_cookies.status(path)["expired"] is True

    @pytest.mark.parametrize("text, says", [
        ('{"not": "cookies"}', "not a cookies.txt"),
        (f".google.com\tTRUE\t/\tTRUE\t{LATER}\tNID\tx\n", "no youtube.com cookies"),
        ("x" * (youtube_cookies.MAX_BYTES + 1), "larger than 1 MB"),
    ])
    def test_refused_files_leave_the_old_ones(self, path, text, says):
        youtube_cookies.set_cookies(path, EXPORT)
        with pytest.raises(youtube_cookies.CookiesRejected, match=says):
            youtube_cookies.set_cookies(path, text)
        assert "SAPISID" in path.read_text()

    def test_clear(self, path):
        youtube_cookies.set_cookies(path, EXPORT)
        youtube_cookies.clear(path)
        assert youtube_cookies.status(path)["present"] is False
        youtube_cookies.clear(path)  # twice is fine


class TestKeepingTheSignInAlive:
    def test_a_refreshed_signed_in_jar_replaces_the_stored_one(self, path):
        youtube_cookies.set_cookies(path, EXPORT)
        refreshed = EXPORT.replace("\tabc", "\trotated")
        assert youtube_cookies.take_back(path, refreshed) is True
        assert "rotated" in path.read_text()

    @pytest.mark.parametrize("jar", ["", "# Netscape HTTP Cookie File\n",
                                     f".youtube.com\tTRUE\t/\tTRUE\t{LATER}\tVISITOR_INFO1_LIVE\tx\n"])
    def test_a_broken_or_signed_out_jar_never_replaces_a_good_one(self, path, jar):
        youtube_cookies.set_cookies(path, EXPORT)
        assert youtube_cookies.take_back(path, jar) is False
        assert "SAPISID" in path.read_text()

    def test_a_refusal_is_news_once_a_day_and_new_cookies_clear_it(self, path):
        youtube_cookies.set_cookies(path, EXPORT)
        now = [1_000_000.0]
        assert youtube_cookies.mark_refused(path, clock=lambda: now[0]) is True
        now[0] += 3600
        assert youtube_cookies.mark_refused(path, clock=lambda: now[0]) is False
        assert youtube_cookies.status(path)["refused_at"] == 1_003_600
        now[0] += 24 * 3600
        assert youtube_cookies.mark_refused(path, clock=lambda: now[0]) is True
        youtube_cookies.set_cookies(path, EXPORT)
        assert youtube_cookies.status(path)["refused_at"] is None


class TestConsole:
    def test_the_owner_uploads_sees_and_removes_them(self, app):
        owner = signed_in(app, OWNER_FIRM, "owner@onyx.test", firm_password=CONSOLE_PASSWORD)
        assert owner.get("/admin/api/youtube-cookies").json()["present"] is False

        put = owner.put("/admin/api/youtube-cookies", json={"cookies": EXPORT})
        assert put.status_code == 200 and put.json()["signed_in"] is True
        assert owner.put("/admin/api/youtube-cookies", json={"cookies": "nope"}).status_code == 400
        assert owner.delete("/admin/api/youtube-cookies").json()["present"] is False

    @pytest.mark.parametrize("email", ["boss@firm.com", "alice@firm.com"])
    def test_a_firms_own_people_cannot(self, app, email):
        client = signed_in(app, email=email)
        assert client.get("/admin/api/youtube-cookies").status_code == 403
        assert client.put("/admin/api/youtube-cookies", json={"cookies": EXPORT}).status_code == 403


class TestCli:
    def test_set_show_and_clear(self, store, tmp_path, capsys):
        export = tmp_path / "cookies.txt"
        export.write_text(EXPORT)
        base = ["--youtube-cookies", str(tmp_path / "kept.txt")]

        assert main([*base, "set-youtube-cookies", str(export)], store=store) == 0
        assert "3 cookies, signed in" in capsys.readouterr().out
        assert main([*base, "clear-youtube-cookies"], store=store) == 0
        assert "No YouTube cookies" in capsys.readouterr().out
        bad = tmp_path / "bad.txt"
        bad.write_text("nothing")
        assert main([*base, "set-youtube-cookies", str(bad)], store=store) == 1
